/* @lc app=leetcode id=3287 lang=kotlin */ class Solution { fun st(dp: Array<BooleanArray>, x: Int, k: Int): Array<BooleanArray> = dp.map { it.copyOf() }.toTypedArray().also { nd -> (1..k).forEach { j -> (0..127).filter { dp[j - 1][it] }.forEach { u -> nd[j][u or x] = true } } } fun maxValue(nums: IntArray, k: Int): Int = Array(k + 1) { j -> BooleanArray(128) { j == 0 && it == 0 } }.let { init -> nums.toList().runningFold(init) { dp, x -> st(dp, x, k) }.let { pre -> nums.toList().reversed().runningFold(init) { dp, x -> st(dp, x, k) }.let { suf -> (k..nums.size - k).maxOf { i -> (0..127).filter { pre[i][k][it] }.maxOf { a -> (0..127).filter { suf[nums.size - i][k][it] }.maxOf { b -> a xor b } } } } } } }